--- index.html
+++ index.html
@@ -32,4 +32,40 @@
 <section class="side-card"><div class="side-heading">ПУТЬ ИСТОРИИ <span id="progressText">0%</span></div><div class="chapter-progress" id="progressBars"><i class="progress-step"></i><i class="progress-step"></i><i class="progress-step"></i><i class="progress-step"></i></div></section></aside></div>
 <footer class="footer"><span>ОДИНОЧНОЕ ПРИКЛЮЧЕНИЕ · ТВОЯ ИСТОРИЯ</span><span class="footer-right">СОЗДАНО <b>♥</b> ИЗ ВООБРАЖЕНИЯ</span></footer>
 </div><div class="toast" id="toast"></div><div class="modal-backdrop" id="modal"><div class="modal"><h2 id="modalTitle">Дневник Миры</h2><div id="modalBody"></div><div class="modal-actions"><button id="modalClose">Вернуться</button></div></div></div>
 <script>
+const initialState=()=>({step:0,health:70,mind:82,trust:0,inventory:[],clues:[],flags:{},history:[],terminal:false});
+let state=loadState();let toastTimer;
+const chapters=[
+ {tag:'ГЛАВА 01  ·  ПРИБЫТИЕ',count:'01 / 04',location:'ОКЕАНСКОЕ ДНО · КАЮТА 04',time:'03:17',title:'Пробуждение',quote:'«Здесь не бывает неправильных решений. Только последствия.»',text:'Сознание возвращается рывком. Красный свет аварийных ламп режет темноту, а за иллюминатором медленно проплывают огни затонувшей станции.\n\nТы не помнишь, как оказалась в каюте. На запястье — браслет с чужим именем. Из динамика доносится шёпот: <em>«Мира… не открывай дверь».</em> Потом тишина. На панели мигают три сообщения.',choices:[
+  {label:'Проверить сообщения на аварийной панели',key:'1',reply:'Ты стираешь иней с панели. Последнее сообщение отправлено шесть часов назад — с твоего собственного терминала.',effect:{mind:-3,trust:5,clue:'Последнее сообщение отправлено тобой самой.',item:'Повреждённый терминал',flag:'checkedPanel'}},
+  {label:'Ответить голосу: «Кто здесь?»',key:'2',reply:'Динамик шипит. «Я — то, что вы оставили внизу». Голос звучит в точности как твой, только старше.',effect:{trust:12,mind:-7,clue:'Голос в динамике похож на твой.',flag:'answeredEcho'}},
+  {label:'Осмотреть дверь и найти выход',key:'3',reply:'Дверь заклинило. Ты находишь за оторванной панелью ручной ключ и прячешь его в карман.',effect:{health:5,item:'Ручной ключ',clue:'Каюта заперта снаружи.',flag:'foundKey'}}
+ ]},
+ {tag:'ГЛАВА 02  ·  ЭХО',count:'02 / 04',location:'КОРИДОР · УЗЕЛ СВЯЗИ',time:'03:29',title:'Голос из глубины',quote:'«Прошлое не просит верить. Оно просто ждёт.»',text:'Коридор встречает тебя водой по щиколотку и тишиной, слишком плотной для пустой станции. На стене свежие царапины: кто-то отсчитывал дни.\n\nТерминал связи оживает сам. <em>«Мира, шлюз три. У нас мало времени».</em> По ту сторону голоса что-то тяжело ударяет в металл.',choices:[
+  {label:'Запросить у голоса кодовое слово',key:'1',reply:'В ответ звучит дата вашей первой экспедиции — её знали только ты и сестра, пропавшая здесь.',effect:{trust:16,mind:-4,clue:'Эхо знает секрет из твоего прошлого.',item:'Код шлюза 3',flag:'trustedEcho'}},
+  {label:'Отследить сигнал до источника',key:'2',reply:'Трассировка ведёт не к шлюзу, а к нижнему архиву. Сигнал проходит через старый биоконтур.',effect:{mind:5,clue:'Сигнал идёт через биоконтур архива.',flag:'tracedSignal'}},
+  {label:'Отключить связь и идти вслепую',key:'3',reply:'Ты выдёргиваешь кабель. Станция вздрагивает — за стеной что-то отвечает гулом.',effect:{health:-8,trust:-5,item:'Изолированный кабель',flag:'cutSignal'}}
+ ]},
+ {tag:'ГЛАВА 03  ·  АРХИВ',count:'03 / 04',location:'НИЖНИЙ УРОВЕНЬ · БИОАРХИВ',time:'03:46',title:'То, что осталось',quote:'«Некоторые ответы меняют не прошлое, а того, кто спрашивал.»',text:'За шлюзом — архив, залитый тусклым бирюзовым свечением. В центре камеры пульсирует прозрачная капсула. Внутри — лицо твоей сестры. Такое же, каким ты помнишь его десять лет назад.\n\nНа стекле проступает отпечаток ладони. Терминал сообщает: <em>«Копия сознания нестабильна. Запуск аварийного сброса — 04:00».</em>',choices:[
+  {label:'Положить ладонь на стекло и заговорить',key:'1',reply:'Капсула отвечает теплом. Сестра открывает глаза: «Ты всё-таки вернулась». В памяти всплывает ночь аварии.',effect:{trust:18,mind:-8,clue:'Сестра помнит ночь аварии и ждала тебя.',flag:'touchedCapsule'}},
+  {label:'Изучить протокол, прежде чем решать',key:'2',reply:'Архив раскрывает запись: сознание сестры копировали в последний момент. Её оригинал не пережил катастрофу.',effect:{mind:8,clue:'Перед тобой цифровая копия — оригинал погиб.',item:'Запись эвакуации',flag:'readProtocol'}},
+  {label:'Остановить сброс любой ценой',key:'3',reply:'Ты перегружаешь контур. Капсула стабилизируется, но аварийное питание уходит в красную зону.',effect:{health:-10,trust:10,clue:'Капсулу удалось удержать, но станция теряет энергию.',flag:'stoppedPurge'}}
+ ]},
+ {tag:'ГЛАВА 04  ·  ВЫБОР',count:'04 / 04',location:'ВНЕШНИЙ ШЛЮЗ · БЕЗДНА',time:'03:59',title:'Последняя минута',quote:'«Конец — это тоже решение. Иногда самое честное.»',text:'По корпусу прокатывается глухой раскат. До сброса секунд. Сестра смотрит на тебя через стекло — или на то место, где камера должна быть.\n\n«Мира, — говорит она, — ты можешь забрать меня с собой. Но тогда станция не переживёт подъём. Или отпустить. Только не называй это спасением». За иллюминатором разгорается тонкая линия рассвета.',choices:[
+  {label:'Забрать капсулу и рискнуть всем',key:'1',ending:'rescue',reply:'Ты отцепляешь капсулу от контура. Вся станция гаснет разом — но в темноте слышен знакомый смешок.'},
+  {label:'Остаться и поговорить до конца',key:'2',ending:'stay',reply:'Ты выключаешь таймер и садишься у стекла. Впервые за десять лет вы говорите не об аварии — а о жизни.'},
+  {label:'Отпустить её и передать запись наверх',key:'3',ending:'release',reply:'Ты отправляешь запись на поверхность. Сестра улыбается, пока свет капсулы мягко растворяется в воде.'}
+ ]}
+];
+function loadState(){try{const saved=JSON.parse(localStorage.getItem('last-signal-save'));return saved?{...initialState(),...saved,flags:saved.flags||{},history:saved.history||[]}:initialState()}catch{return initialState()}}
+function save(){try{localStorage.setItem('last-signal-save',JSON.stringify(state));document.getElementById('saveText').textContent='ИГРА СОХРАНЕНА'}catch{document.getElementById('saveText').textContent='АВТОСОХРАНЕНИЕ'}}
+function render(){const c=chapters[Math.min(state.step,3)];document.getElementById('chapterTag').textContent=c.tag;document.getElementById('chapterCount').textContent=c.count;document.getElementById('sceneLocation').textContent=c.location;document.getElementById('sceneTime').textContent=c.time;document.getElementById('sceneTitle').textContent=state.terminal?state.endingTitle:c.title;document.getElementById('gmQuote').textContent=state.terminal?'«История закончилась. Но она останется с тобой.»':c.quote;
+ const extra=state.step===1&&state.flags.checkedPanel?' На браслете вспыхивает надпись: <em>«Ты уже была здесь».</em>':state.step===2&&state.flags.trustedEcho?' Под ладонью стекло отвечает ровным теплом.':state.step===3&&state.flags.readProtocol?' Терминал выводит на экран: <em>«Последняя запись: Мира Вейл».</em>':'';
+ document.getElementById('narrative').innerHTML=state.terminal?state.endingText:c.text+extra;
+ const list=document.getElementById('choices');list.innerHTML='';if(state.terminal){const b=document.createElement('button');b.className='choice';b.textContent='Начать новую историю';b.onclick=resetGame;list.appendChild(b)}else c.choices.forEach((choice,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`${escapeHtml(choice.label)} <span class="choice-key">${i+1}</span>`;b.onclick=()=>choose(i);list.appendChild(b)});
+ document.getElementById('actionInput').disabled=state.terminal;document.querySelector('.send-button').disabled=state.terminal;document.getElementById('healthValue').textContent=state.health+'%';document.getElementById('healthMeter').style.width=state.health+'%';document.getElementById('mindValue').textContent=state.mind+'%';document.getElementById('mindMeter').style.width=state.mind+'%';document.getElementById('trustValue').textContent=state.trust?state.trust+'%':'—';document.getElementById('trustMeter').style.width=state.trust+'%';document.getElementById('inventory').innerHTML=state.inventory.length?state.inventory.map(x=>`<span class="item-chip">${escapeHtml(x)}</span>`).join(''):'<span class="empty-inventory">Пока ничего.</span>';document.getElementById('clues').innerHTML=state.clues.length?state.clues.slice(-4).map(x=>`<div class="clue">${escapeHtml(x)}</div>`).join(''):'<div class="clue-empty">Тайны раскрываются по ходу истории.</div>';document.getElementById('progressText').textContent=state.terminal?'100%':Math.round(state.step/4*100)+'%';document.querySelectorAll('.progress-step').forEach((el,i)=>el.classList.toggle('done',i<state.step+(state.terminal?1:0)));save()}
+function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
+function choose(index){if(state.terminal)return;const choice=chapters[state.step].choices[index];if(!choice)return;applyEffect(choice.effect);state.history.push({chapter:state.step+1,choice:choice.label,reply:choice.reply});if(state.step<3){const response=choice.reply;state.step++;render();showNarrativeReply(response)}else finish(choice);}
+function applyEffect(effect={}){for(const key of ['health','mind','trust'])if(effect[key])state[key]=Math.max(0,Math.min(100,state[key]+effect[key]));if(effect.item&&!state.inventory.includes(effect.item))state.inventory.push(effect.item);if(effect.clue&&!state.clues.includes(effect.clue))state.clues.push(effect.clue);if(effect.flag)state.flags[effect.flag]=true}
+function showNarrativeReply(reply){const el=document.getElementById('narrative');el.innerHTML+=`\n\n<em>${escapeHtml(reply)}</em>`;window.scrollTo({top:0,behavior:'smooth'})}
+function finish(choice){const e=choice.ending;let title,text;if(e==='rescue'){title=state.trust>=25?'Эхо на поверхности':'Цена возвращения';text=state.trust>=25?'Подъём занимает три дня. Когда капсула открывается, сестра смотрит на тебя и произносит твоё имя. Не копия. Не совсем. Но теперь вы снова можете выбирать вместе.': 'Капсула приходит в себя, но её память обрывочна. Ты спасла голос — не человека. На поверхности начинается новая, трудная история.'}else if(e==='stay'){title='Тихая глубина';text='Аварийный сброс останавливается. На поверхности станция «Атлас» числится пропавшей, но в темноте вы успеваете вспомнить всё важное. Иногда быть рядом — и есть спасение.'}else{title=state.mind>=70?'Свет наверху':'Сообщение домой';text=state.mind>=70?'Запись уходит к рассвету. На поверхности её слушают тысячи людей. Ты поднимаешься одна — и впервые за десять лет чувствуешь, что сестра не исчезла бесследно.':'Сигнал едва проходит сквозь помехи. Ты выбираешься наверх с пустыми руками, но с правдой, которую больше не придётся нести в одиночку.'}state.terminal=true;state.endingTitle=title;state.endingText=`${escapeHtml(choice.reply)}\n\n<em>${escapeHtml(text)}</em>\n\n<small>ТВОЙ ПУТЬ: ${state.trust>=25?'ДОВЕРИЕ':'СОМНЕНИЕ'} · СОСТОЯНИЕ ${state.health}% · РАССУДОК ${state.mind}%</small>`;state.history.push({chapter:4,choice:choice.label,reply:text});render();document.getElementById('chapterTag').textContent='ЭПИЛОГ  ·  ТВОЙ ФИНАЛ';document.getElementById('chapterCount').textContent='ЗАВЕРШЕНО';showToast('Твоя история завершена')}

input.newString:
function choose(index){if(state.terminal)return;const choice=chapters[state.step].choices[index];if(choice)processChoice(choice)}
function processChoice(choice,customReply){applyEffect(choice.effect);const reply=customReply||choice.reply;state.history.push({chapter:state.step+1,choice:customReply?'Твоё действие: '+customReply.input:choice.label,reply});if(state.step<3){state.step++;render();showNarrativeReply(reply)}else finish({...choice,reply})}
function actInOwnWords(raw){if(state.terminal)return;const input=raw.trim();if(!input)return;const words=input.toLowerCase(),options=chapters[state.step].choices;let index=0;
 if(/голос|эхо|ответ|сестр|имя|поговор|спрос|довер|ладон|стекл|капсул|остаться|рядом/.test(words))index=state.step===0?1:state.step===1?0:state.step===2?0:1;
 else if(/двер|ключ|выход|сбеж|уйти|отключ|перереж|авари|останов|спасти|забра|поднять|риск/.test(words))index=state.step===0?2:state.step===1?2:state.step===2?2:0;
 else if(/провер|панел|сообщ|терминал|изуч|запис|архив|узна|след|иск|анализ|код/.test(words))index=state.step===0?0:state.step===1?1:state.step===2?1:2;
 const base=options[index],effect=JSON.parse(JSON.stringify(base.effect||{}));let reply;
 if(/помощ|спас|береж|защит|сест|вместе|довер|верю|прости/.test(words)){effect.trust=(effect.trust||0)+5;reply=`Ты выбираешь действовать с заботой. Станция отвечает едва заметным теплом: «Я запомню, как ты это сказала». ${base.reply}`}
 else if(/страш|бою|паник|не знаю|сомнева|правда/.test(words)){effect.mind=(effect.mind||0)-3;reply=`Мастер отмечает твоё сомнение. Страх здесь не слабость — он напоминает, что ещё есть что терять. ${base.reply}`}
 else if(/быстр|скорее|немедлен|сроч|тороп/.test(words)){effect.health=(effect.health||0)-2;reply=`Ты не теряешь ни секунды. Решение принято прежде, чем тревога успевает тебя остановить. ${base.reply}`}
 else{reply=`Ты решаешь: «${input}». Мастер вплетает это в историю — детали твоего поступка останутся с тобой. ${base.reply}`}
 processChoice({...base,effect},{input,reply});}

