61: function loadState(){try{const saved=JSON.parse(localStorage.getItem('last-signal-save'));return saved?{...initialState(),...saved,flags:saved.flags||{},history:saved.history||[]}:initialState()}catch{return initialState()}}
62: function save(){try{localStorage.setItem('last-signal-save',JSON.stringify(state));document.getElementById('saveText').textContent='ИГРА СОХРАНЕНА'}catch{document.getElementById('saveText').textContent='АВТОСОХРАНЕНИЕ'}}
63: function render(){const c=chapters[Math.min(state.step,3)];document.getElementById('chapterTag').textContent=state.terminal?'ЭПИЛОГ  ·  ТВОЙ ФИНАЛ':c.tag;document.getElementById('chapterCount').textContent=state.terminal?'ЗАВЕРШЕНО':c.count;document.getElementById('sceneLocation').textContent=c.location;document.getElementById('sceneTime').textContent=c.time;document.getElementById('sceneTitle').textContent=state.terminal?state.endingTitle:c.title;document.getElementById('gmQuote').textContent=state.terminal?'«История закончилась. Но она останется с тобой.»':c.quote;
64:  const extra=state.step===1&&state.flags.checkedPanel?' На браслете вспыхивает надпись: <em>«Ты уже была здесь».</em>':state.step===2&&state.flags.trustedEcho?' Под ладонью стекло отвечает ровным теплом.':state.step===3&&state.flags.readProtocol?' Терминал выводит на экран: <em>«Последняя запись: Мира Вейл».</em>':'';
65:  document.getElementById('narrative').innerHTML=state.terminal?state.endingText:c.text+extra;
66:  const list=document.getElementById('choices');list.innerHTML='';if(state.terminal){const b=document.createElement('button');b.className='choice';b.textContent='Начать новую историю';b.onclick=resetGame;list.appendChild(b)}else c.choices.forEach((choice,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`${escapeHtml(choice.label)} <span class="choice-key">${i+1}</span>`;b.onclick=()=>choose(i);list.appendChild(b)});
67:  document.getElementById('actionInput').disabled=state.terminal;document.querySelector('.send-button').disabled=state.terminal;document.getElementById('healthValue').textContent=state.health+'%';document.getElementById('healthMeter').style.width=state.health+'%';document.getElementById('mindValue').textContent=state.mind+'%';document.getElementById('mindMeter').style.width=state.mind+'%';document.getElementById('trustValue').textContent=state.trust?state.trust+'%':'—';document.getElementById('trustMeter').style.width=state.trust+'%';document.getElementById('inventory').innerHTML=state.inventory.length?state.inventory.map(x=>`<span class="item-chip">${escapeHtml(x)}</span>`).join(''):'<span class="empty-inventory">Пока ничего.</span>';document.getElementById('clues').innerHTML=state.clues.length?state.clues.slice(-4).map(x=>`<div class="clue">${escapeHtml(x)}</div>`).join(''):'<div class="clue-empty">Тайны раскрываются по ходу истории.</div>';document.getElementById('progressText').textContent=state.terminal?'100%':Math.round(state.step/4*100)+'%';document.querySelectorAll('.progress-step').forEach((el,i)=>el.classList.toggle('done',i<state.step+(state.terminal?1:0)));save()}
68: function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
69: function choose(index){if(state.terminal)return;const choice=chapters[state.step].choices[index];if(choice)processChoice(choice)}
70: function processChoice(choice,customReply){applyEffect(choice.effect);const reply=customReply?customReply.reply:choice.reply;state.history.push({chapter:state.step+1,choice:customReply?'Твоё действие: '+customReply.input:choice.label,reply});if(state.step<3){state.step++;render();showNarrativeReply(reply)}else finish({...choice,reply})}
71: function actInOwnWords(raw){if(state.terminal)return;const input=raw.trim();if(!input)return;const words=input.toLowerCase(),options=chapters[state.step].choices;let index=0;
72:  if(/голос|эхо|ответ|сестр|имя|поговор|спрос|довер|ладон|стекл|капсул|остаться|рядом/.test(words))index=state.step===0?1:state.step===1?0:state.step===2?0:1;
73:  else if(/двер|ключ|выход|сбеж|уйти|отключ|перереж|авари|останов|спасти|забра|поднять|риск/.test(words))index=state.step===0?2:state.step===1?2:state.step===2?2:0;
74:  else if(/провер|панел|сообщ|терминал|изуч|запис|архив|узна|след|иск|анализ|код/.test(words))index=state.step===0?0:state.step===1?1:state.step===2?1:2;
75:  const base=options[index],effect=JSON.parse(JSON.stringify(base.effect||{}));let reply;
76:  if(/помощ|спас|береж|защит|сест|вместе|довер|верю|прости/.test(words)){effect.trust=(effect.trust||0)+5;reply=`Ты выбираешь действовать с заботой. Станция отвечает едва заметным теплом: «Я запомню, как ты это сказала». ${base.reply}`}
77:  else if(/страш|бою|паник|не знаю|сомнева|правда/.test(words)){effect.mind=(effect.mind||0)-3;reply=`Мастер отмечает твоё сомнение. Страх здесь не слабость — он напоминает, что ещё есть что терять. ${base.reply}`}
78:  else if(/быстр|скорее|немедлен|сроч|тороп/.test(words)){effect.health=(effect.health||0)-2;reply=`Ты не теряешь ни секунды. Решение принято прежде, чем тревога успевает тебя остановить. ${base.reply}`}
79:  else{reply=`Ты решаешь: «${input}». Мастер вплетает это в историю — детали твоего поступка останутся с тобой. ${base.reply}`}
80:  processChoice({...base,effect},{input,reply});}
81: function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
82: function openModal(title,content,actions=[]){const modal=document.getElementById('modal');document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=content;const buttons=document.querySelector('.modal-actions');buttons.innerHTML='<button id="modalClose">Вернуться</button>'+actions.map(a=>`<button class="${a.className||''}" id="${a.id}">${escapeHtml(a.label)}</button>`).join('');document.getElementById('modalClose').onclick=()=>modal.classList.remove('open');modal.classList.add('open');actions.forEach(a=>{document.getElementById(a.id).onclick=a.onClick})}
83: function openJournal(){const rows=state.history.length?state.history.map(h=>`<div class="clue"><span style="color:#e6a079;font:9px var(--mono)">ГЛАВА ${h.chapter}</span><br><b>${escapeHtml(h.choice)}</b><br>${escapeHtml(h.reply)}</div>`).join(''):'<p>Пока здесь чистая страница. Твои решения будут записываться по ходу истории.</p>';openModal('Дневник Миры',`<p>Воспоминания, которые мастер сохраняет для тебя.</p>${rows}`)}
84: function resetGame(){state=initialState();document.getElementById('modal').classList.remove('open');render();showToast('Новая история начинается')}
85: document.getElementById('actionForm').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('actionInput');if(!input.value.trim())return;const value=input.value;input.value='';actInOwnWords(value)});
86: document.getElementById('journalButton').addEventListener('click',openJournal);
87: document.getElementById('resetButton').addEventListener('click',()=>{if(!state.history.length){resetGame();return}openModal('Начать заново?',`<p>Текущий путь сохранён в дневнике только до начала новой игры. Ты уверена, что хочешь начать сначала?</p>`,[{id:'confirmReset',label:'Начать сначала',className:'danger',onClick:resetGame}])});
88: document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')});
89: document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('modal').classList.remove('open');if(!state.terminal&&['1','2','3'].includes(e.key)&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName))choose(Number(e.key)-1)});
90: render();
