function applyEffect(effect={}){for(const key of ['health','mind','trust'])if(effect[key])state[key]=Math.max(0,Math.min(100,state[key]+effect[key]));if(effect.item&&!state.inventory.includes(effect.item))state.inventory.push(effect.item);if(effect.clue&&!state.clues.includes(effect.clue))state.clues.push(effect.clue);if(effect.flag)state.flags[effect.flag]=true}
function showNarrativeReply(reply){const el=document.getElementById('narrative');el.innerHTML+=`\n\n<em>${escapeHtml(reply)}</em>`;window.scrollTo({top:0,behavior:'smooth'})}
function finish(choice){const e=choice.ending;let title,text;if(e==='rescue'){title=state.trust>=25?'Эхо на поверхности':'Цена возвращения';text=state.trust>=25?'Подъём занимает три дня. Когда капсула открывается, сестра смотрит на тебя и произносит твоё имя. Не копия. Не совсем. Но теперь вы снова можете выбирать вместе.': 'Капсула приходит в себя, но её память обрывочна. Ты спасла голос — не человека. На поверхности начинается новая, трудная история.'}else if(e==='stay'){title='Тихая глубина';text='Аварийный сброс останавливается. На поверхности станция «Атлас» числится пропавшей, но в темноте вы успеваете вспомнить всё важное. Иногда быть рядом — и есть спасение.'}else{title=state.mind>=70?'Свет наверху':'Сообщение домой';text=state.mind>=70?'Запись уходит к рассвету. На поверхности её слушают тысячи людей. Ты поднимаешься одна — и впервые за десять лет чувствуешь, что сестра не исчезла бесследно.':'Сигнал едва проходит сквозь помехи. Ты выбираешься наверх с пустыми руками, но с правдой, которую больше не придётся нести в одиночку.'}state.terminal=true;state.endingTitle=title;state.endingText=`${escapeHtml(choice.reply)}\n\n<em>${escapeHtml(text)}</em>\n\n<small>ТВОЙ ПУТЬ: ${state.trust>=25?'ДОВЕРИЕ':'СОМНЕНИЕ'} · СОСТОЯНИЕ ${state.health}% · РАССУДОК ${state.mind}%</small>`;state.history.push({chapter:4,choice:choice.label,reply:text});render();document.getElementById('chapterTag').textContent='ЭПИЛОГ  ·  ТВОЙ ФИНАЛ';document.getElementById('chapterCount').textContent='ЗАВЕРШЕНО';showToast('Твоя история завершена')}

