import math, struct, zlib

def make_png(size, path):
    rows = bytearray()
    scale = size / 512
    for y in range(size):
        rows.append(0)
        for x in range(size):
            X, Y = (x + .5) / scale, (y + .5) / scale
            dx, dy = X - 256, Y - 256
            r = math.hypot(dx, dy)
            if max(abs(dx), abs(dy)) > 200 and r > 216:
                color = (16, 17, 20)
            else:
                glow = max(0, 1 - math.hypot((X-368)*.75, (Y-112)*.75)/430)
                color = (int(16+glow*38), int(17+glow*29), int(20+glow*34))
                if abs(r-156) < 2: color = (93, 69, 65)
                if abs(r-118) < 1.5: color = (48, 52, 59)
                line = min(abs(dx), abs(dy), abs(abs(dx)-abs(dy))/math.sqrt(2)) < 7 and 126 < r < 187
                if line:
                    t = min(1, max(0, (dx+dy+300)/600))
                    color = (int(255-24*t), int(194-93*t), int(138-66*t))
                if abs(r-36) < 5: color = (242, 144, 94)
                if r < 11: color = (242, 189, 132)
            rows.extend(color)
    def chunk(kind, data):
        return struct.pack('>I', len(data)) + kind + data + struct.pack('>I', zlib.crc32(kind + data) & 0xffffffff)
    raw = b'\x89PNG\r\n\x1a\n'
    raw += chunk(b'IHDR', struct.pack('>IIBBBBB', size, size, 8, 2, 0, 0, 0))
    raw += chunk(b'IDAT', zlib.compress(bytes(rows), 9)) + chunk(b'IEND', b'')
    with open(path, 'wb') as f: f.write(raw)

